const cs = canary.filter(r=>r.path=='/search');
const ss = stable.filter(r=>r.path=='/search');
print('canary /search n=', cs.length, 'stable /search n=', ss.length);
print('canary pct', [50,90,95,99,99.9].map(p=>p+':'+pct(cs.map(r=>r.ms),p)).join(' '));
print('stable pct', [50,90,95,99,99.9].map(p=>p+':'+pct(ss.map(r=>r.ms),p)).join(' '));
const slowC = cs.filter(r=>r.ms>200), slowS = ss.filter(r=>r.ms>200);
print('canary /search >200ms count=', slowC.length, 'pctOfCanarySearch=', (100*slowC.length/cs.length).toFixed(2)+'%');
print('stable /search >200ms count=', slowS.length);
print('canary slow ms sorted:', slowC.map(r=>r.ms).sort((a,b)=>a-b).join(','));
print('canary slow times t:', slowC.map(r=>Math.round(r.t)).sort((a,b)=>a-b).join(','));
print('canary slow statuses:', slowC.map(r=>r.status).join(','));
print('max canary /search ms=', Math.max(...cs.map(r=>r.ms)), 'max stable /search ms=', Math.max(...ss.map(r=>r.ms)));
// other paths tails on canary
for (const p of ['/browse','/checkout']) {
  const c = canary.filter(r=>r.path==p), s = stable.filter(r=>r.path==p);
  print(p, 'canary p99=', pct(c.map(r=>r.ms),99), 'max=', Math.max(...c.map(r=>r.ms)), '| stable p99=', pct(s.map(r=>r.ms),99), 'max=', Math.max(...s.map(r=>r.ms)));
}
print('total 5xx canary=', canary.filter(r=>r.status>=500).length, 'stable=', stable.filter(r=>r.status>=500).length);
print('non-200 statuses canary:', JSON.stringify(canary.reduce((a,r)=>{a[r.status]=(a[r.status]||0)+1;return a;},{})));
print('non-200 statuses stable:', JSON.stringify(stable.reduce((a,r)=>{a[r.status]=(a[r.status]||0)+1;return a;},{})));

const cs = canary.filter(r=>r.path=='/search').map(r=>r.ms).sort((a,b)=>a-b);
const ss = stable.filter(r=>r.path=='/search').map(r=>r.ms).sort((a,b)=>a-b);
const cslow = cs.filter(m=>m>200), sslow = ss.filter(m=>m>200);
print("C1 CANARY_SEARCH_OVER_200MS=" + cslow.length + "/" + cs.length + " STABLE_SEARCH_OVER_200MS=" + sslow.length + "/" + ss.length + " canary_slow_min=" + cslow[0] + " canary_slow_max=" + cslow[cslow.length-1] + " stable_search_max=" + ss[ss.length-1]);
const p99c = pct(cs,99), p99s = pct(ss,99);
print("C2 CANARY_SEARCH_P99=" + p99c + " STABLE_SEARCH_P99=" + p99s + " RATIO_GE_5=" + (p99c/p99s >= 5));
const c5 = canary.filter(r=>r.status>=500).length, s5 = stable.filter(r=>r.status>=500).length;
print("C3 CANARY_5XX=" + c5 + " STABLE_5XX=" + s5 + " CANARY_N=" + canary.length + " STABLE_N=" + stable.length);
const w=[0,0,0,0];
const slowRows = canary.filter(r=>r.path=='/search'&&r.ms>200);
slowRows.forEach(r=>{ w[Math.min(3,Math.floor(r.t/30))]++; });
print("C4 WINDOW_COUNTS=" + w.join(",") + " ALL_FOUR_WINDOWS=" + w.every(x=>x>0) + " first_t=" + slowRows[0].t + " last_t=" + slowRows[slowRows.length-1].t);
const pc = pct(canary.map(r=>r.ms),95), ps = pct(stable.map(r=>r.ms),95);
print("C5 OVERALL_P95 canary=" + pc + " stable=" + ps + " DIFF_LE_5=" + (Math.abs(pc-ps)<=5));
const f=(arr,p)=>pct(arr.filter(r=>r.path==p).map(r=>r.ms),99);
const bc=f(canary,'/browse'), bs=f(stable,'/browse'), kc=f(canary,'/checkout'), ks=f(stable,'/checkout');
print("C6 BROWSE_P99 c=" + bc + " s=" + bs + " CHECKOUT_P99 c=" + kc + " s=" + ks + " OTHER_PATHS_NOT_WORSE=" + (bc<=bs+5 && kc<=ks+5));

const q=(a,p)=>{const v=a.map(r=>r.ms).sort((x,y)=>x-y);return v[Math.min(v.length-1,Math.ceil(p*v.length)-1)];};
const cse=canary.filter(r=>r.path=='/search'), sse=stable.filter(r=>r.path=='/search');
const cslow=cse.filter(r=>r.ms>200), sslow=sse.filter(r=>r.ms>200);
const cms=cslow.map(r=>r.ms).sort((a,b)=>a-b);
print('C1 SLOW c='+cslow.length+'/'+cse.length+' s='+sslow.length+'/'+sse.length+' c_slow_range='+cms[0]+'-'+cms[cms.length-1]+' s_max='+Math.max(...sse.map(r=>r.ms)));
const cp=q(cse,0.99), sp=q(sse,0.99), c5=q(cse,0.5), s5=q(sse,0.5);
print('C2 P99 c='+cp+' s='+sp+' RATIO_GE_8='+(cp>=8*sp)+' P50 c='+c5+' s='+s5+' P50_DIFF_LE_5='+(Math.abs(c5-s5)<=5));
print('C3 SLOW_STATUSES='+[...new Set(cslow.map(r=>r.status))].join(',')+' CANARY_5XX='+canary.filter(r=>r.status>=500).length+' STABLE_5XX='+stable.filter(r=>r.status>=500).length);
const w=[0,0,0,0]; cslow.forEach(r=>w[Math.min(3,Math.floor(r.t/30))]++);
const ts=cslow.map(r=>r.t).sort((a,b)=>a-b);
print('C4 WINDOWS='+w.join(',')+' ALL4='+w.every(x=>x>0)+' first_t='+ts[0].toFixed(1)+' last_t='+ts[ts.length-1].toFixed(1));
let ok=true, info='';
for(const p of ['/browse','/checkout']){const c=canary.filter(r=>r.path==p), s=stable.filter(r=>r.path==p); const a=q(c,0.99), b=q(s,0.99); if(a>b+10) ok=false; info+=p+' c_p99='+a+' s_p99='+b+' ';}
print('C5 '+info+'OTHER_OK='+ok);

